const countries=['china','korea','mongolia','japan','philippines','indonesia','malaysia','singapore','brazil','uruguay','argentina','russia','south-africa','eswatini','lesotho'];
const colorMetrics=['none','population','populationDensity','gdp','gdpPerCapita'];
export const controls=['province-layer','prefecture-layer','other-layer','label-layer','satellite-layer','satellite-opacity','capital-layer','water-layer','k-province-layer','k-prefecture-layer','k-label-layer','k-capital-layer','m-province-layer','m-district-layer','m-label-layer','m-capital-layer','j-province-layer','j-second-layer','j-label-layer','ph-province-layer','ph-second-layer','ph-label-layer','id-province-layer','id-second-layer','id-label-layer','my-province-layer','my-second-layer','my-label-layer','sg-province-layer','sg-second-layer','sg-label-layer','south-outlines','south-names','south-city-dots','ru-province-layer','ru-second-layer','ru-label-layer','za-province-layer','za-second-layer','za-third-layer','za-label-layer','za-settlement-layer','za-city-layer','sz-province-layer','sz-second-layer','sz-label-layer','ls-province-layer','ls-second-layer','ls-label-layer'];
export function validate(value){
 if(!value||value.v!==1||!countries.includes(value.country)||!Array.isArray(value.center)||value.center.length!==2||!value.center.every(Number.isFinite)||value.center[0]<-180||value.center[0]>(value.country==='russia'?200:180)||value.center[1]<-65||value.center[1]>80||!Number.isFinite(value.zoom)||value.zoom<.5||value.zoom>16)return null;
 const layers={};for(const id of controls){const v=value.layers?.[id];if(id==='satellite-opacity'){if(Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=100)layers[id]=String(v);}else if(typeof v==='boolean')layers[id]=v;}
 const language=value.country==='south-africa'?(['both','en','af','zu','xh','ss','st','tn','nso','ts','ve','nr'].includes(value.language)?value.language:'both'):value.country==='singapore'?(['zh','ms','en','ta'].includes(value.language)?value.language:'en'):(['en','local','both'].includes(value.language)?value.language:'both');
 return {v:1,country:value.country,center:value.center,zoom:value.zoom,selection:typeof value.selection==='string'||typeof value.selection==='number'?String(value.selection).slice(0,80):null,scope:(value.country==='brazil'?['states','ddd','cep']:value.country==='korea'?['KP','KR']:value.country==='argentina'?['cities']:[]).includes(value.scope)?value.scope:'',mode:value.country==='south-africa'&&value.mode===3?3:value.mode===2?2:1,locked:value.locked===true,language,colorBy:colorMetrics.includes(value.colorBy)?value.colorBy:"none",layers};
}
export function fromHash(hash){try{const m=/^#(china|korea|mongolia|japan|philippines|indonesia|malaysia|singapore|brazil|uruguay|argentina|russia|south-africa|eswatini|lesotho)\/view=(.*)$/i.exec(hash);if(!m||m[2].length>10000)return null;const value=validate(JSON.parse(decodeURIComponent(m[2])));return value?.country===m[1].toLowerCase()?value:null;}catch{return null;}}
export function hashFor(view){const valid=validate(view);return valid?'#'+valid.country+'/view='+encodeURIComponent(JSON.stringify(valid)):null;}
export function read(country,storage){try{return validate(JSON.parse(storage.getItem('boundary-atlas-view-v1-'+country)));}catch{return null;}}
export function write(view,storage){const valid=validate(view);if(!valid)return;try{storage.setItem('boundary-atlas-view-v1-'+valid.country,JSON.stringify(valid));}catch{}}
